local _, ns = ...
-- Original Spanish summaries based on quest text present in Forever 1.60.1.70938.
-- No future outcomes, hidden motives or Classic-only lore are added.
-- Every anchor must occur in the current description before a summary is used.
ns.Stories = {
    [153] = { anchors = { "pañuelos", "banda" }, text = "Galiaan lleva tiempo siguiendo los movimientos cambiantes de los Defias. Sus pañuelos de cuero rojo permiten identificar a los miembros de la banda; reunirlos aporta pruebas de tu intervención contra quienes operan en Páramos de Poniente." },
    [12] = { anchors = { "Milicia Popular", "defender" }, text = "Los habitantes de Páramos de Poniente han organizado la Milicia Popular para defender sus tierras. Ayudas a Gryan Mantorrecio a frenar a los Defias que ocupan las granjas y los alrededores de las minas, para que la región vuelva a ser habitable." },
    [13] = { anchors = { "saqueadores Defias", "Milicia" }, text = "Los Defias siguen saqueando las minas y las haciendas de Páramos de Poniente. Gryan te encarga contener esos ataques como parte de tu colaboración con la Milicia Popular: el objetivo es proteger lo que todavía conservan los habitantes de la región." },
    [4722] = { anchors = { "tortuga", "Gwennyth" }, text = "Una tortuga murió tras quedar varada en Costa Oscura y los múrlocs han aprovechado sus restos. Todavía quedan muestras que podrían servir a Gwennyth para investigar las muertes de criaturas marinas." },
    [944] = { anchors = { "Martillo Crepuscular", "Señores de la Tierra" }, text = "Onus está preocupado por la presencia del Martillo Crepuscular en La Espada del Maestro, donde cayó uno de los antiguos seres que el culto venera. Vas a investigar qué buscan allí y a mantenerlo informado mediante su magia de adivinación." },
    [1639] = { anchors = { "Bartleby", "enseñarte" }, text = "Tu instructor quiere comprobar cómo te desenvuelves antes de continuar tu formación. Pedirle su jarra a Bartleby es la provocación elegida para ponerte a prueba: sabe que el veterano no va a entregártela por las buenas." },
    [965] = { anchors = { "Balthule", "proteger Auberdine" }, text = "Elissa envió a Balthule a vigilar los sucesos extraños de la Torre de Althalaxx, pero todavía no ha regresado. Vas a comprobar si está a salvo y qué pudo haberle ocurrido durante una misión destinada a proteger Auberdine." },
    [98394] = { anchors = { "espíritu felino", "tutor" }, text = "Adoptar la forma felina requiere aprender de su espíritu, además de dominar la magia. Buscas al gran espíritu felino para comprender la naturaleza del animal, siguiendo el camino de aprendizaje de otros druidas." },
    [92909] = { anchors = { "cosechadores", "escape" }, text = "Ozwin llegó desde Forjaz para reparar los cosechadores que aterrorizan los campos, pero las máquinas lo acorralaron. Las piezas que recuperas le permitirían construir un dispositivo con el que escapar: estás rescatando al técnico que vino a resolver el problema." },
    [2139] = { anchors = { "animales enfermos", "madre del cubil" }, text = "Tharnariun reconoce que sacrificar animales enfermos solo ha aliviado temporalmente el sufrimiento del bosque. Pide una última intervención contra la madre del cubil, en una cueva al noreste, con la esperanza de no tener que encargar más muertes." },
    [102] = { anchors = { "Ventormenta nos ha abandonado", "gnolls" }, text = "Danuvin siente que Ventormenta ha abandonado a los habitantes de Páramos de Poniente, así que los propios granjeros han decidido resistir. Tu patrulla protege a quienes permanecen allí frente a los gnolls que parecen colaborar con los bandidos de Las Minas de la Muerte." },
    [3524] = { anchors = { "Templo de la Luna", "investigar" }, text = "Cada vez más criaturas marinas quedan varadas y mueren en las playas de Costa Oscura. Gwennyth investiga el fenómeno por encargo del Templo de la Luna, pero los múrlocs le impiden acercarse a los cadáveres; necesita muestras para continuar el estudio." },
    [1097] = { anchors = { "Grimand Elmore", "enanos" }, text = "Grimand Elmore necesita ayuda para enviar un paquete al norte. Te ponen en contacto con él para facilitar la entrega y mantener los vínculos con los enanos, que también forman parte de la ayuda mutua entre los aliados." },
    [97894] = { anchors = { "Gorbold", "no sé nada" }, text = "Borgus dejó de recibir noticias de su hermano desde que Gorbold se instaló como mercader en Auberdine. Aprovechas el viaje a Costa Oscura para comprobar que se encuentra bien; detrás del encargo comercial hay una preocupación familiar." },
    [29] = { anchors = { "adorno", "destreza mental" }, text = "Esta prueba druídica exige combinar concentración y destreza física. El adorno del lago se deteriora rápidamente, de modo que llevarlo al santuario sirve para demostrar que puedes actuar con decisión y completar el rito a tiempo." },
    [1001] = { anchors = { "Zumbang", "reparada" }, text = "Sigues las instrucciones de Zumbang para reparar otra de sus cajas mecánicas. Los ojos de trillador son los componentes que necesita este aparato: la tarea mantiene en funcionamiento su peculiar red de máquinas parlantes." },
    [2159] = { anchors = { "hierbas", "druidas" }, text = "La persona que te entrega el paquete todavía tiene obligaciones con los druidas de Cañada Umbría y no puede marcharse. Te haces cargo del envío de hierbas para que llegue a la posada de Dolanaar sin interrumpir ese trabajo." },
    [6122] = { anchors = { "agua potable", "envenenamiento" }, text = "Los druidas sospechan que el agua de Salto de Fonroca está envenenando a los ciervos. Como esa fuente abastece a buena parte de la región, tu muestra ayudará a Alanndarian a investigar un peligro que puede afectar a muchos más seres vivos." },
    [151] = { anchors = { "Blanchy", "carro" }, text = "Blanchy está exhausta y la avería del carro dejó a los Cejade sin la posibilidad de continuar su viaje. Buscas alimento para que su yegua se recupere mientras la familia intenta salir adelante en los peligrosos campos de Páramos de Poniente." },
    [98340] = { anchors = { "Dendrita", "entrenamiento druídico" }, text = "Tus progresos te permiten continuar la formación como druida. Dendrita te espera en Claro de la Luna para guiar el siguiente paso de tu aprendizaje; el viaje responde a esa convocatoria de tu mentor." },
    [4811] = { anchors = { "cristal rojo", "hostiles" }, text = "Los lechúcicos lunares están volviéndose hostiles y parecen dirigirse hacia un misterioso cristal rojo. Glynda necesita confirmar que el cristal existe y reunir información para valorar el peligro que representa para Auberdine." },
    [91733] = { anchors = { "carreta", "suministros" }, text = "La carreta de Ormin volcó y la corriente arrastró sus herramientas y provisiones. Los animales y los múrlocs le impiden recuperarlas por su cuenta, así que tu ayuda busca devolverle lo que perdió en el accidente." },
    [6181] = { anchors = { "suministro", "armaduras" }, text = "La gente de Páramos de Poniente recibe poca ayuda directa de Ventormenta y sus reservas de armaduras se están agotando. Lewis depende de su contacto Osric para reponerlas: llevas la petición que puede mantener equipados a quienes defienden la región." },
    [26] = { anchors = { "formas animales", "agua" }, text = "Tu formación druídica ha llegado al aprendizaje de una forma animal que permite desenvolverse en el agua. Vas a reunirte con Dendrita, del Círculo Cenarion, para recibir la instrucción necesaria para continuar ese camino." },
    [963] = { anchors = { "Anaia", "espíritu atormentado" }, text = "Cerellean descubrió que Anaia, su amada, sigue atrapada como un espíritu atormentado en las ruinas de Ameth'Aran. Incapaz de enfrentarse él mismo a ese dolor, te pide que la liberes: la misión trata de poner fin a un sufrimiento que ha durado miles de años." },
    [40] = { anchors = { "múrlocs", "Dughan" }, text = "Remy ha visto cómo los múrlocs invaden los ríos del este de Elwynn y atacan a sus habitantes. Dughan está ocupado con otras amenazas y no le da suficiente importancia, así que intentas conseguir que la guardia tome el peligro en serio." },
    [949] = { anchors = { "Martillo Crepuscular", "intenciones" }, text = "La presencia del Martillo Crepuscular en La Espada del Maestro sigue sin explicación. Buscas pruebas de sus intenciones para que Onus pueda preparar una respuesta con información, en lugar de actuar a ciegas contra el culto." },
    [436] = { anchors = { "Vetaferro", "retraso" }, text = "La excavación de Vetaferro apenas avanza a pesar de recibir suministros. Como su responsable tiene fama de trabajador, sospechan que hay obstáculos que todavía desconocen; hablas con quien organiza los trabajos para entender qué está pasando." },
    [91725] = { anchors = { "gnolls", "castigo" }, text = "Unos gnolls emboscaron a Blixie y la obligaron a abandonar los suministros de encantamiento que Theocritus le había encargado. Quiere recuperarlos antes de volver: teme pasar semanas limpiando los experimentos de Polimorfia si regresa sin el paquete." },
    [36] = { anchors = { "ladrones", "receta" }, text = "Los ladrones han vuelto demasiado peligrosa la granja de los Furlbrow y la familia se prepara para marcharse. Antes de irse, Verna quiere hacer llegar su receta de estofado a su vecina Salma Saldean." },
    [1861] = { anchors = { "corrientes de magia", "contaminación" }, text = "Las grandes luchas mágicas han alterado corrientes de energía que antes eran estables. Jennea necesita estudiar sus consecuencias y tu muestra del Lago Espejo permitirá comprobar si esas alteraciones están contaminando el agua cercana a Ventormenta." },
    [1656] = { anchors = { "Rito de la Fuerza", "padre" }, text = "Un joven intenta cumplir el Rito de la Fuerza y, al mismo tiempo, un encargo de su padre. Como no tiene fuerzas para ambas obligaciones, llevas las pieles a Pezuña de Sangre para que pueda concentrarse en su prueba." },
    [947] = { anchors = { "poción", "nuevo mal" }, text = "Barithras necesita setas para una poción, pero los ancianos le han advertido que la cueva donde crecen podría albergar un nuevo mal. Tu viaje tiene un doble propósito: conseguir los ingredientes y comprobar si hay una amenaza en ese lugar." },
    [35] = { anchors = { "múrlocs", "Thomas" }, text = "Los informes sobre los múrlocs de Elwynn todavía necesitan confirmación. Thomas lleva días vigilando el puente oriental y puede aportar información directa: buscas su testimonio para que Dughan conozca la situación real." },
    [87760] = { anchors = { "nagas", "dominaron" }, text = "El estudio de las muestras reveló que los nagas esclavizan a las criaturas marinas y se deshacen de las que dejan de servirles. Vas a enfrentarte a una de sus domadoras y recuperar sus instrumentos para responder a ese abuso." },
    [954] = { anchors = { "Bashal'Aran", "aura azul" }, text = "Los seres demoníacos de Bashal'Aran se alimentan de la magia de las ruinas y cada vez son más poderosos. Sin embargo, evitan un santuario de aura azul; investigarlo podría explicar qué los mantiene alejados de ese punto." },
    [6285] = { anchors = { "Lewis", "cajón" }, text = "Llevas de vuelta el cargamento de Osric al intendente Lewis. Esta entrega cierra el recado de suministros para Páramos de Poniente: el viaje en grifo permite que el material llegue a quienes lo esperan en la Colina del Centinela." },
    [98393] = { anchors = { "Dendrita", "entrenamiento druídico" }, text = "Te convocan de nuevo a Claro de la Luna para continuar tu formación. Dendrita quiere guiar el siguiente paso de tu aprendizaje druídico ahora que ya dominas la magia necesaria para llegar hasta él." },
    [4723] = { anchors = { "trillador gigante", "misterio" }, text = "Un trillador de tamaño extraordinario apareció muerto en la costa y no está claro qué pudo acabar con él. Los múrlocs que comen sus restos no parecen capaces de haberlo derribado; recuperas muestras para que Gwennyth investigue el misterio." },
    [9] = { anchors = { "granjeros", "vigías de la cosecha" }, text = "Los bandidos han expulsado a muchos granjeros, pero Saldean se niega a abandonar su hogar. Los vigías de la cosecha también han invadido los campos, y tu ayuda busca despejar las tierras de quienes todavía resisten allí." },
    [61] = { anchors = { "Morgan", "velas" }, text = "William ya preparó las velas que espera su hermano Morgan en Ventormenta, pero no puede viajar para entregarlas. Te encargas de completar ese intercambio entre ambos hermanos y su tienda." },
    [92742] = { anchors = { "veneno", "aguas" }, text = "Un veneno está corrompiendo los campos de Páramos de Poniente y todavía no se conoce su origen. Analizar el agua de los pozos es el primer paso para saber qué está llegando al suelo de las granjas y cómo empezar a combatirlo." },
    [94774] = { anchors = { "Catedral de la Luz", "instrucción" }, text = "Tus progresos han llamado la atención de los superiores de tu orden. Laurena te espera en la Catedral de la Luz porque consideran que ya estás en condiciones de recibir una nueva etapa de instrucción." },
    [952] = { anchors = { "mensaje", "Onus" }, text = "Fandral necesita mantener el contacto con Onus y los ancianos de Costa Oscura. Te confía un mensaje que forma parte de esa comunicación entre los guardianes y sus aliados, y tú haces posible que las noticias lleguen a su destinatario." },
    [982] = { anchors = { "capitanes", "tripulación" }, text = "Dos barcos fueron abordados por múrlocs antes de llegar a Auberdine y sus capitanes murieron en los naufragios. Recuperas sus documentos y efectos personales para los tripulantes supervivientes, que todavía necesitan lo que quedó bajo el mar." },
    [6281] = { anchors = { "Osric", "nota de Lewis" }, text = "Continúas el envío de la petición de Lewis hacia Osric en Ventormenta. Esta etapa consiste en aprovechar la conexión por grifo para que su mensaje llegue a la ciudad y pueda continuar el encargo de suministros." },
    [6121] = { anchors = { "veneno", "Cenarius" }, text = "La capacidad de purgar venenos es un don de Cenarius que tus maestros quieren que comprendas antes de darlo por sentado. Dendrita te enseñará a afrontar el envenenamiento sin recurrir de inmediato a la magia, para entender el valor de ese poder." },
    [65] = { anchors = { "Hermandad Defias", "Wiley" }, text = "Gryan quiere ir más allá de contener los ataques: necesita saber quién dirige a los Defias y dónde se esconden. Buscas a Wiley, un contacto que le debe un favor, para empezar a penetrar en la organización responsable del desplazamiento de los granjeros." },
    [98397] = { anchors = { "Mathrengyl", "felino" }, text = "Dendrita considera que ya aprendiste lo necesario para volver con Mathrengyl. Regresas a Darnassus para llevar esa preparación a la siguiente etapa de tu formación y acercarte a la forma felina." },
    [184] = { anchors = { "escrituras", "Cejade" }, text = "Las escrituras que encontraste muestran que los Cejade fueron presionados para perder sus tierras y que alguien pensaba falsificar documentos. Devolvérselas significa recuperar una prueba de propiedad para una familia expulsada de su hogar." },
    [353] = { anchors = { "Pico Tormenta", "arma" }, text = "Grimand terminó un arma encargada por el montaraz Pico Tormenta, pero su destinatario está destinado muy lejos de la ciudad. Te ocupas de que el trabajo del herrero llegue al enano que lo espera en Loch Modan." },
    [1002] = { anchors = { "Zumbang", "colmillos" }, text = "Zumbang te dirige hacia otra de sus cajas mecánicas averiadas. Los colmillos sirven para reparar esta unidad y continuar poniendo en funcionamiento sus aparatos, aunque las explicaciones del inventor se vuelven cada vez más confusas." },
    [948] = { anchors = { "Onus", "Salto de Fonroca" }, text = "Onus se enteró de tu exploración de Salto de Fonroca y quiere conocer lo que viste. Su convocatoria es urgente: tu experiencia puede ayudar a los ancianos a entender lo que sucede en esa parte de Costa Oscura." },
    [98025] = { anchors = { "búho", "viajantes" }, text = "Jai'vhanel ha empezado a atacar a los viajeros cerca de Auberdine. El concejo pide que alguien detenga a esta ave para proteger el camino y lleve una de sus plumas negras a Glynda como prueba." },
    [8] = { anchors = { "Renee", "Plaga" }, text = "Una carta necesita llegar a Renee, la tabernera de Rémol. El remitente ofrece un pago por llevarla y recomienda la posada como un lugar acogedor donde otras víctimas de la Plaga intentan reconstruir sus vidas." },
    [95065] = { anchors = { "peces", "suministros" }, text = "A Gilbert le queda muy poco cebo y quiere seguir disfrutando de la pesca en el puerto de Ventormenta. Lo ayudas a reabastecerse con la vendedora de la ciudad: es un favor sencillo para alguien cuyo placer es pasar el día junto al agua." },
    [951] = { anchors = { "Martillo Crepuscular", "magia élfica" }, text = "El papiro que recuperaste sugiere que el Martillo Crepuscular intenta aprovechar magia élfica antigua para traer de vuelta a sus maestros. Onus necesita estudiar reliquias de Mathystra para comprender ese método y poder responder al plan del culto." },
    [985] = { anchors = { "Bosque Negro", "amenaza" }, text = "Terenthis considera que el campamento de los Bosque Negro al sur de Auberdine es una de las mayores amenazas para su gente. Después de demostrar que puedes rastrearlos, te pide intervenir directamente para reducir ese peligro." },
    [123] = { anchors = { "Coleccionista", "oro" }, text = "La nota que encontraste registra entregas de oro procedente de las minas de Elwynn a una persona conocida como el Coleccionista. Se la llevas a Dughan para que la guardia pueda investigar qué hay detrás de esos movimientos." },
    [399] = { anchors = { "brújula", "ladrones" }, text = "El hogar familiar de Baros Alexston fue incendiado y ahora está ocupado por ladrones. Su primera brújula sigue escondida en la granja; recuperarla permitiría devolverle un recuerdo de su infancia en Páramos de Poniente." },
    [64] = { anchors = { "reloj de bolsillo", "boda" }, text = "Los Furlbrow huyeron de su granja cuando llegaron los asaltantes y dejaron un reloj de gran valor sentimental. El padre de Verna lo regaló el día de su boda, y su dueño quiere recuperarlo del armario de la casa." },
    [1638] = { anchors = { "Harry Burlguard", "veterano" }, text = "Tu instructor reconoce tus progresos, pero cree que todavía necesitas aprender de alguien con más experiencia. Te envía a Harry Burlguard, un veterano de Ventormenta que puede enseñarte técnicas para sobrevivir a futuros combates." },
    [983] = { anchors = { "invento", "mantenimiento" }, text = "Zumbang creó unas cajas que permiten hablar con personas lejanas, pero necesitan reparaciones constantes. Reúnes componentes para poner una de ellas en marcha y ayudar al inventor a mantener su red de comunicación." },
    [38] = { anchors = { "estofado", "ingredientes" }, text = "Salma quiere preparar estofado de Páramos de Poniente y necesita ingredientes de la región. Conseguir carne, verduras y otros componentes permite ayudarla a reunir lo necesario para su receta." },
    [1640] = { anchors = { "jarra", "manos" }, text = "Bartleby se niega a entregar su jarra y responde a tu provocación con un desafío. Tienes que demostrar tu capacidad de lucha en el enfrentamiento que tu instructor quiso provocar como parte de la prueba." },
    [1003] = { anchors = { "Zumbang", "525" }, text = "La siguiente reparación de Zumbang te lleva a otra caja mecánica escondida al sur de Auberdine. Sigues reuniendo componentes para reactivar sus aparatos, esta vez siguiendo las instrucciones cada vez más desordenadas del inventor." },
    [2158] = { anchors = { "Farley", "descansar" }, text = "Te recomiendan la posada de Farley como un lugar seguro donde recuperarte del viaje. El encargo te presenta una ayuda cotidiana para la vida de aventurero: conocer a quien ofrece descanso y provisiones en Villadorada." },
    [22] = { anchors = { "empanada", "hígados" }, text = "Salma tiene casi listo su pastel de carne: la masa, las hierbas y la salsa están preparadas. Solo le faltan hígados de dentosangre para terminar su receta y servir la comida." },
    [4728] = { anchors = { "criatura", "Gwennyth" }, text = "Una criatura marina yace parcialmente destripada en la playa. Las herramientas y una carretilla abandonadas sugieren un intento de estudiarla. Aunque los múrlocs han aprovechado el cadáver, todavía quedan muestras útiles para la investigación de Gwennyth." },
    [957] = { anchors = { "prisión", "llama" }, text = "Asterion está atrapado por un sello creado por un poderoso Altonato. La antigua llama azul de Ameth'Aran podría destruirlo: buscas un modo de romper el vínculo mágico que mantiene su prisión." },
    [92744] = { anchors = { "corrupción", "hambre" }, text = "La contaminación de los cultivos de Páramos de Poniente podría estar extendiéndose al mar y amenazar el alimento de Ventormenta. Las branquias de los múrlocs sirven como muestra para detectar toxinas en el agua y comprobar el alcance del problema." },
    [4762] = { anchors = { "río", "corrupción" }, text = "El río Fonroca está contaminado y Thundris teme que sus aguas afecten pronto a Auberdine. Sospecha de los fúrbolgs que viven río arriba, aunque cree que existe una causa más profunda. Necesita una muestra para investigar." },
    [2161] = { anchors = { "comida", "miedo" }, text = "Ukor llevó comida al Valle de los Retos para ayudar, pero allí no la necesitan. El camino de regreso le da miedo por las bestias, así que trasladas el cargamento a Cerrotajo para que llegue a la posada sin exponerlo a ese peligro." },
    [92910] = { anchors = { "cosechador", "gólems" }, text = "Encontraste una pieza de cosechador que parece estar casi intacta. Se la llevas a Ozwin porque su conocimiento de los gólems puede darle un uso o revelar su importancia; todavía no sabes qué descubrirá al examinarla." },
    [958] = { anchors = { "Altonato", "reliquias" }, text = "En las ruinas de Ameth'Aran permanecen espíritus Altonato con sus antiguos instrumentos mágicos. Thundris quiere retirar y destruir esas reliquias, ligadas a un pasado de magia cuyos errores dejaron las ruinas que ahora estás explorando." },
    [6261] = { anchors = { "Lewis", "equipados" }, text = "Osric ya reunió el material que pidió Lewis para quienes combaten en Páramos de Poniente. Te ocupas de despachar el cajón por la ruta de grifos para que la falta de equipo no debilite la defensa de la región." },
    [92745] = { anchors = { "metales tóxicos", "Defias" }, text = "Las muestras de los pozos revelaron metales tóxicos que podrían inutilizar los campos durante décadas. Los Defias explotan las minas con otras criaturas como mano de obra, y tu intervención busca frenar esa actividad mientras se intenta contener la contaminación." },
    [109] = { anchors = { "Gryan", "Milicia Popular" }, text = "Gryan dirige la Milicia Popular que intenta proteger las granjas de Páramos de Poniente. Te recomiendan presentarte ante él porque tu experiencia en combate puede ayudar a los habitantes que defienden la región." },
    [2160] = { anchors = { "Tannok", "escolta" }, text = "La persona que prepara el envío no puede atravesar el paso sin una escolta y la posada de Kharanos espera sus suministros. Aprovechas tu propio viaje para que el paquete llegue a Tannok sin tener que esperar varios días." },
    [381] = { anchors = { "Cruzada Escarlata", "no-muertos" }, text = "La Cruzada Escarlata está instalando un campamento y persigue a todos los no muertos, sin distinguir a los Renegados de la Plaga. Arren quiere actuar antes de que ataquen: defiendes a tu gente frente a un enemigo que se niega a reconocer esa diferencia." },
    [2138] = { anchors = { "cura no funciona", "osos" }, text = "La cura de Tharnariun no ha funcionado y los osos enfermos siguen causando daño. Te pide sacrificarlos como una medida dolorosa para proteger a los demás habitantes del bosque, sabiendo que eso solo reduce el daño y no acaba con la plaga." },
}
